function v6Band(s){return '<div class="v6-task-band"><span>'+(s.taskLines||[]).map(R).join('<br>')+'</span>'+(s.sampleId?jumpButton(s.sampleId,0,'Xem lại mẫu'):'')+'</div>'}
function v6Worked(s){
 const m=s.worked;
 const gap=(answer)=>'<span class="v6-gap" data-worked-gap="'+s.id+'">Ô cuối: em đề xuất...</span><span data-worked-answer="'+s.id+'" hidden>'+R(answer)+'</span>';
 let table='<table class="v6-model-table"><thead><tr><th>Mục cần ghi</th><th>Bài làm mẫu</th></tr></thead><tbody>'+m.labels.map((label,i)=>'<tr><th>'+R(label)+'</th><td>'+(i===4?gap(m.values[i]):R(m.values[i]))+'</td></tr>').join('')+'</tbody></table>';
 if(s.targetId==='02-17')table='<table class="v6-model-table v6-model-three"><thead><tr><th>Vai</th><th>Việc cần làm</th><th>Em đề xuất ai?</th></tr></thead><tbody><tr><th>Chọn nhiệm vụ</th><td>Chọn giấy và nhựa.</td><td>Em A</td></tr><tr><th>Chuẩn bị ví dụ</th><td>Viết thẻ có tên đúng.</td><td>Em B</td></tr><tr><th>Đóng vai hệ thống</th><td>Làm theo quy tắc.</td><td>Em C</td></tr><tr><th>Kiểm tra</th><td>So với vật thật.</td><td>'+gap('Em D')+'</td></tr></tbody></table>';
 if(s.targetId==='07-12')table='<table class="v6-model-table v6-model-three"><thead><tr><th>Nên / Không nên</th><th>Vì sao?</th><th>Cách dùng phù hợp</th></tr></thead><tbody><tr><th>Không nộp nguyên bài AI viết.</th><td>Em chưa tự luyện viết.</td><td>Xin gợi ý câu hỏi hoặc dàn ý.</td></tr><tr><th>Phần em tự làm</th><td>Em tự nêu ý và viết bài.</td><td>'+gap('Em đọc lại và kiểm nội dung.')+'</td></tr></tbody></table>';
 return '<div class="v6-model-head"><span>'+R(m.context)+'</span></div><div class="v6-worked-grid"><div>'+table+'<div class="v6-quick"><b>30 giây · '+R(m.question)+'</b>'+B('worked-reveal','Mở ô cuối','secondary')+'</div></div><aside class="v6-model-why"><h3>Vì sao điền như vậy?</h3>'+m.why.map((x,i)=>'<div><span aria-hidden="true">'+(i+1)+'</span><p>'+R(x)+'</p></div>').join('')+'<div class="v6-model-visual">'+v6Visual(s)+'</div></aside></div>';
}
function v6Content(s){if(s.type==='cover')return '<div class="cover-main"><h1>'+coverTitle()+'</h1></div><div class="v6-cover-picture">'+v6Glyph({1:'cup',2:'person',3:'image',4:'check',5:'book',6:'lock',7:'clock',8:'document',9:'clock',10:'source',11:'document',12:'video'}[D.id])+'</div><div class="cover-bottom">'+E(D.mode)+' · '+(D.id<=8?'45 phút':'khoảng 45 phút tự làm')+'</div>';
 if(s.type==='divider')return '<p class="v6-divider-join">'+R(s.connector)+'</p><div class="divider-main"><h1>'+R(s.title)+'</h1></div>'+star();
 if(s.type==='worked')return v6Worked(s);
 if(s.type==='worksheet')return sheet(s);
 if(s.type==='video')return media(s);
 if(s.type==='submission')return '<div class="ai6-grid2 v6-submission"><div>'+list(s.screen||[],s.subtexts)+v6Visual(s)+'</div><div class="ai6-panel"><h3>Phần việc của em</h3>'+field(s.id+'-contribution','Em đã làm gì?','')+field(s.id+'-next','Em sẽ dùng cách kiểm nào lần sau?','')+B('export','Tải bài làm')+'</div></div>';
 let actions='';if(s.recordTarget)actions+=jumpButton(s.recordTarget,s.recordPage||0);if(s.publicComparison)actions+=B('translation-answer','Chiếu bảng đối chiếu','secondary');if(s.imageTool)actions+='<a class="ai6-action secondary" href="'+E(CONFIG.imageToolUrl||'https://www.google.com/imghp?hl=vi')+'" target="_blank" rel="noopener">Mở công cụ ảnh</a>';if(s.type==='home')actions+=B('export','Tải bài làm');if(s.sourceAccess)actions+=sourceLinks();
 const roles=s.rolesV6?'<div class="v6-role-row">'+s.rolesV6.map(x=>'<span>'+R(x)+'</span>').join('')+'</div>':'';
 const steps3=renderSteps3(s);
 let picture='';
 if(s.photo&&s.photo.file){picture='<div class="v6-picture">'+photoCard(s)+'</div>'}
 else if(s.steps3&&s.steps3.length){picture='<div class="v6-picture">'+v6Visual(s)+'</div>'}
 else{picture='<div class="v6-picture">'+v6Visual(s)+'</div>'}
 const hasSteps3=!!(s.steps3&&s.steps3.length);
 if(hasSteps3&&(!s.screen||!s.screen.length)){
  return '<div class="v6-content-grid v6-content-steps3"><div class="v6-copy">'+steps3+roles+(actions?'<div class="ai6-actions">'+actions+'</div>':'')+'</div>'+picture+'</div>';
 }
 return '<div class="v6-content-grid"><div class="v6-copy">'+list(s.screen||[],s.subtexts)+steps3+roles+(actions?'<div class="ai6-actions">'+actions+'</div>':'')+'</div>'+picture+'</div>';
}
function revealWorked(id,visible=true,remote=false){workedReveal[id]=visible;document.querySelectorAll('[data-worked-answer="'+id+'"]').forEach(x=>{x.hidden=!visible;const b=x.closest('.ai6-slide')?.querySelector('[data-action="worked-reveal"]');if(b){b.textContent=visible?'Ẩn ô cuối':'Mở ô cuối';b.setAttribute('aria-expanded',String(visible))}});document.querySelectorAll('[data-worked-gap="'+id+'"]').forEach(x=>x.hidden=visible);if(T&&!remote)send({type:'ai6-worked',id,visible})}

if(document.body.classList.contains('ai6-gallery')){document.body.innerHTML=D.slides.map(s=>'<div class="gallery-label">TIẾT '+ID+' · SLIDE '+s.number+' / '+D.count+'</div><div class="gallery-item" id="g-'+s.id+'"><div class="ai6-canvas">'+renderSlide(s).replace('class="ai6-slide ','class="ai6-slide active ')+'</div></div>').join('');D.slides.filter(s=>s.type==='worksheet'&&!(s.id==='01-09')).forEach(s=>renderSheet(s,undefined,0));if(new URLSearchParams(location.search).get('pages')==='all'){for(const s of D.slides.filter(x=>x.worksheet?.pages)){for(let k=1;k<s.worksheet.pages.length;k++){const label=document.createElement('div');label.className='gallery-label';label.textContent='TIẾT '+ID+' · SLIDE '+s.number+' · PHIẾU BƯỚC '+(k+1);document.body.append(label);const g=document.createElement('div');g.className='gallery-item';g.id='g-'+s.id+'-p'+k;g.innerHTML='<div class="ai6-canvas">'+renderSlide(s).replace('class="ai6-slide ','class="ai6-slide active ')+'</div>';document.body.append(g);renderPage(s,k,g)}}}const fitGallery=()=>document.querySelectorAll('.gallery-item').forEach(g=>g.querySelector('.ai6-canvas').style.transform='scale('+g.clientWidth/1600+')');if(new URLSearchParams(location.search).get('answers')==='all')D.slides.filter(x=>x.type==='worked').forEach(x=>revealWorked(x.id,true,true));v6Clean(document.body);fitGallery();document.fonts.ready.then(()=>{fitGallery();document.body.dataset.ready='1'});addEventListener('resize',fitGallery);return;}
document.body.innerHTML=(P?presenterShell():toolbar())+dialog();
if(!P)D.slides.filter(s=>s.type==='worksheet'&&!(s.id==='01-09')).forEach(s=>renderSheet(s));restore();
document.addEventListener('input',e=>{if(A)return;const el=e.target;if(el.dataset.save){state[el.dataset.save]=el.value;save();updateTotals();if(T)send({type:'ai6-field',key:el.dataset.save,value:el.value})}});document.addEventListener('change',e=>{if(A)return;const el=e.target;if(el.dataset.save){state[el.dataset.save]=el.value;save();updateTotals();if(T)send({type:'ai6-field',key:el.dataset.save,value:el.value})}if(el.id==='minutes')onAction('timer-reset')});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(A&&b.dataset.action!=='fullscreen')return;if(b.dataset.jump){const target=D.slides.findIndex(s=>s.id===b.dataset.jump);if(target>=0){go(target);const s=active();if(s.worksheet?.pages)renderPage(s,Number(b.dataset.jumpPage)||0)}return}if(b.dataset.cue!=null){const pane=$('teacherNotePane'),section=pane?.querySelectorAll('.ai6-note-section')[Number(b.dataset.cue)];if(section)pane.scrollTo({top:pane.scrollTop+section.getBoundingClientRect().top-pane.getBoundingClientRect().top-72,behavior:'smooth'});return;}if(b.dataset.action){onAction(b.dataset.action);return}if(b.dataset.go!=null){go(Number(b.dataset.go));$('dialog').close();return}const wrap=b.closest('[data-sheet]');if(wrap){const s=D.slides.find(x=>x.id===wrap.dataset.sheet),v=viewPages[s.id]||{mode:'questions',page:0};if(b.dataset.page!=null)renderPage(s,Number(b.dataset.page));if(b.dataset.sheetMode)renderSheet(s,b.dataset.sheetMode,0);if(b.hasAttribute('data-q-next'))renderSheet(s,v.mode,v.page+1);if(b.hasAttribute('data-q-prev'))renderSheet(s,v.mode,v.page-1)}});
document.addEventListener('keydown',e=>{if(A){if(e.key.toLowerCase()==='f')onAction('fullscreen');return}if(publicView){if(e.key==='Escape'){e.preventDefault();showPublic(null)}return}if(e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,textarea,select,video,[contenteditable]')||document.querySelector('dialog[open]'))return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();go(current+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();go(current-1)}if(e.key==='Home')go(0);if(e.key==='End')go(D.count-1);if(e.key.toLowerCase()==='m')onAction('outline');if(e.key.toLowerCase()==='n')onAction('notes');if(e.key.toLowerCase()==='f')onAction('fullscreen')});
function receive(msg){if(msg?.lesson!==D.id||msg?.session!==session)return;if(A&&msg.type==='ai6-worked-state'){workedReveal=msg.values||{};D.slides.filter(x=>x.type==='worked').forEach(x=>revealWorked(x.id,!!workedReveal[x.id],true));return}if(A&&msg.type==='ai6-worked'){revealWorked(msg.id,msg.visible,true);return}
if(msg.type==='ai6-slide'&&msg.index!==current)go(msg.index,false);
if(msg.type==='ai6-ready'&&!A){sync();send({type:'ai6-state',values:state,pages:viewPages});if(T)setProjectionStatus('Đang chiếu · Chỉ slide ở cửa sổ ngoài')}
if(A&&msg.type==='ai6-state'){state=msg.values||{};Object.entries(msg.pages||{}).forEach(([id,v])=>{const s=D.slides.find(x=>x.id===id);if(s)renderSheet(s,v.mode,v.page)});restore();updateTotals();lockAudience()}
if(A&&msg.type==='ai6-field'){state[msg.key]=msg.value;restore();updateTotals()}
if(A&&msg.type==='ai6-sheet'){const s=D.slides.find(x=>x.id===msg.slide);if(s)renderSheet(s,msg.mode,msg.page)}
if(A&&msg.type==='ai6-action'&&['check-class','reset-class'].includes(msg.action))onAction(msg.action,true);
if(A&&msg.type==='ai6-public')showPublic(msg.view,false);if(A&&msg.type==='ai6-summary')showVideoSummary(msg.visible,true);if(A&&msg.type==='ai6-media')applyAudienceMedia(msg);if(A&&msg.type==='ai6-stop')window.close();if(!A&&T&&msg.type==='ai6-ping')setProjectionStatus('Đang chiếu · Chỉ slide ở cửa sổ ngoài');
}

try{channel=new BroadcastChannel('ai6-'+ID+'-'+session);channel.onmessage=e=>receive(e.data)}catch(e){}
window.addEventListener('message',e=>{const m=e.data;let resumed=false;if(!A&&T&&!popup&&e.source&&m?.lesson===D.id&&m?.session===session&&['ai6-ready','ai6-ping'].includes(m.type)&&e.origin===location.origin){popup=e.source;resumed=true}if(e.source!==window.opener&&e.source!==popup)return;receive(m);if(resumed){sync();send({type:'ai6-state',values:state,pages:viewPages})}});
